import fs from 'node:fs';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';
const hash=p=>createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const p=JSON.parse(fs.readFileSync('CURRENT_CHECKPOINT.json'));
assert.equal(p.goal.status,'active');assert.equal(p.goal.requirements,71);assert.equal(p.goal.optionalIdeas,8);
assert.equal(p.activeWork.current.ownerPreviewPolicy.restartPermitted,false);
const dir='F:/VisibleMedicine/recovery/checkpoints/20261024-guide-proof-index-history';assert(!fs.existsSync(dir));fs.mkdirSync(dir);
fs.copyFileSync('CURRENT_CHECKPOINT.json',dir+'/CURRENT_BEFORE.json',fs.constants.COPYFILE_EXCL);
const names=['pendingUpperVascularReasoning','pendingNestedTourLibraryPause','pendingCranialXrayEpoch'];
const originalFields=Object.fromEntries(names.map(key=>['activeWork.current.'+key,p.activeWork.current[key]]));
assert(Object.values(originalFields).every(Boolean));
const archive={at:new Date().toISOString(),previousArchive:p.historyArchive,originalFields};
fs.writeFileSync(dir+'/history.json',JSON.stringify(archive,null,2)+'\n',{flag:'wx'});
fs.writeFileSync(dir+'/field-index.json',JSON.stringify({originalPaths:Object.keys(originalFields),archiveSha256:hash(dir+'/history.json'),previousArchivePreserved:true},null,2)+'\n',{flag:'wx'});
p.historyArchive={path:dir+'/history.json',sha256:hash(dir+'/history.json'),fieldIndex:dir+'/field-index.json',allHistoryRetained:true,priorArchiveIn:'previousArchive',readPolicy:'Read original JSON paths only for relevant older facts. Missing details never imply approval, completion or permission.'};
const current=p.activeWork.current;
const upper=current.pendingUpperVascularReasoning;
current.pendingUpperVascularReasoning={checkpoint:upper.checkpoint,checkpointSha256:upper.checkpointSha256,atlasHead:upper.atlasHead,fullWebsiteIntegrationPending:false,composedInto:upper.composedInto,composedIntoSha256:upper.composedIntoSha256,detailsAt:p.historyArchive.path+'#originalFields.activeWork.current.pendingUpperVascularReasoning',clinicalApproval:false,previewChanged:false,installed:false};
const nested=current.pendingNestedTourLibraryPause;
current.pendingNestedTourLibraryPause={checkpoint:nested.checkpoint,checkpointSha256:nested.checkpointSha256,baseline:nested.baseline,fullTypesBuildBrowserRuntimeRebindingPending:true,rootRendererMetadataPending:true,detailsAt:p.historyArchive.path+'#originalFields.activeWork.current.pendingNestedTourLibraryPause',previewChanged:false,installed:false};
const cranial=current.pendingCranialXrayEpoch;
current.pendingCranialXrayEpoch={checkpoint:cranial.checkpoint,checkpointSha256:cranial.checkpointSha256,testOnly:true,productChanged:false,composedInto:cranial.composedInto,integrationPending:cranial.integrationPending,olderPendingFieldsNotApprovals:true,detailsAt:p.historyArchive.path+'#originalFields.activeWork.current.pendingCranialXrayEpoch',previewChanged:false,installed:false};
const before=JSON.parse(fs.readFileSync(dir+'/CURRENT_BEFORE.json'));
for(const key of ['goal','safety','coordination'])assert.deepEqual(p[key],before[key]);
for(const key of ['ownerPreviewPolicy','currentInstalled','activeExecutionSessions','latestWebsiteCandidate'])assert.deepEqual(current[key],before.activeWork.current[key]);
const restored=structuredClone(p);restored.historyArchive=before.historyArchive;for(const key of names)restored.activeWork.current[key]=before.activeWork.current[key];assert.deepEqual(restored,before);
const text=JSON.stringify(p,null,2)+'\n';assert(Buffer.byteLength(text)<64000);fs.writeFileSync('CURRENT_CHECKPOINT.json',text);
console.log(JSON.stringify({bytes:Buffer.byteLength(text),archive:p.historyArchive.path,sha256:p.historyArchive.sha256,allOriginalFieldsAndArchiveChainPreserved:true}));
